<?php
namespace AutoDealership\Admin;
use AutoDealership\Content\OfferPublishingService as Service;
use AutoDealership\Content\PublicOfferView;
defined('ABSPATH') || exit;

final class OfferPublishingPage {
	private static function t(string $ar,string $en):string{return \AutoDealership\Core\Localization::language()==='en'?$en:$ar;}
	public static function url(int $id=0):string{return add_query_arg(array('page'=>'adc-offer-publishing')+($id?array('post_id'=>$id):array()),admin_url('admin.php'));}
	public static function boot():void {
		add_action('admin_menu',static function(){add_submenu_page('adc-area-content',self::t('عروض الموقع','Website offers'),self::t('عروض الموقع','Website offers'),'edit_car_offers','adc-offer-publishing',array(self::class,'render'));remove_submenu_page('adc-area-content','edit.php?post_type=car_offer');},110);
		add_action('admin_init',static function(){if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'||wp_doing_ajax()){return;}$target=self::legacy_destination($GLOBALS['pagenow']??'',$_GET);if($target){wp_safe_redirect($target);exit;}},20);
		add_filter('get_edit_post_link',static fn($url,$id)=>get_post_type($id)==='car_offer'?self::url((int)$id):$url,20,2);
		add_action('admin_enqueue_scripts',static function(){if(($_GET['page']??'')!=='adc-offer-publishing'){return;}wp_enqueue_media();wp_enqueue_style('adc-publishing',plugins_url('assets/css/catalog-publishing.css',ADC_FILE),array(),ADC_VERSION);wp_enqueue_script('adc-publishing',plugins_url('assets/js/catalog-publishing.js',ADC_FILE),array('media-views'),ADC_VERSION,true);});
		add_action('admin_post_adc_offer_save',array(self::class,'save'));add_action('admin_post_adc_offer_status',array(self::class,'status'));
	}
	public static function legacy_destination(string $screen,array $query):string {
		if($screen==='edit.php'&&($query['post_type']??'')==='car_offer'){return self::url();}if($screen==='post-new.php'&&($query['post_type']??'')==='car_offer'){return add_query_arg('new',1,self::url());}if($screen==='post.php'&&($query['action']??'edit')==='edit'&&get_post_type(absint($query['post']??0))==='car_offer'){return self::url(absint($query['post']));}return '';
	}
	private static function states():array{return array('publish'=>self::t('منشور','Published'),'draft'=>self::t('مسودة','Draft'),'pending'=>self::t('بانتظار المراجعة','Pending review'),'private'=>self::t('خاص','Private'),'future'=>self::t('مجدول','Scheduled'),'trash'=>self::t('في السلة','In trash'));}
	public static function render():void {
		if(!current_user_can('edit_car_offers')){wp_die('Forbidden','',array('response'=>403));}$id=absint($_GET['post_id']??0);
		echo '<div class="wrap adc-publishing adc-offer-publishing" dir="'.(\AutoDealership\Core\Localization::language()==='en'?'ltr':'rtl').'"><header class="adc-publishing-header"><h1>'.esc_html(self::t('عروض الموقع','Website offers')).'</h1><a class="button button-primary" href="'.esc_url(add_query_arg('new',1,self::url())).'">'.esc_html(self::t('إضافة عرض','Add offer')).'</a></header><p>'.esc_html(self::t('إدارة العروض التسويقية المرتبطة بسيارات الموقع. ظهور العرض يتطلب سيارة متوفرة وسعرًا صالحًا وعرضًا غير منتهٍ.','Manage promotional offers linked to website vehicles. Visibility requires an available vehicle, a valid price and an unexpired offer.')).'</p>';
		$error=get_transient('adc_offer_error_'.get_current_user_id());if($error){delete_transient('adc_offer_error_'.get_current_user_id());echo '<div class="notice notice-error"><p>'.esc_html(__($error,'auto-dealership-core')).'</p></div>';}if(isset($_GET['saved'])){echo '<div class="notice notice-success"><p>'.esc_html(self::t('تم حفظ العرض.','Offer saved.')).'</p></div>';}
		if($id||!empty($_GET['new'])){self::editor($id);}else{self::listing();}echo '</div>';
	}
	private static function listing():void {
		global $wpdb;$search=sanitize_text_field(wp_unslash($_GET['search']??''));$status=sanitize_key($_GET['status']??'');$states=self::states();$page=max(1,absint($_GET['paged']??1));
		echo '<form method="get" class="adc-publishing-filters"><input type="hidden" name="page" value="adc-offer-publishing"><label>'.esc_html(self::t('البحث في العروض','Search offers')).'<input name="search" value="'.esc_attr($search).'"></label><label>'.esc_html(self::t('حالة النشر','Publication status')).'<select name="status"><option value="">'.esc_html(self::t('الكل','All')).'</option>';foreach($states as$key=>$label){echo '<option value="'.$key.'" '.selected($status,$key,false).'>'.esc_html($label).'</option>';}echo '</select></label><button class="button">'.esc_html(self::t('بحث','Search')).'</button></form>';
		$args=array('post_type'=>'car_offer','post_status'=>isset($states[$status])?$status:array_keys($states),'s'=>$search,'posts_per_page'=>20,'paged'=>$page);if(!current_user_can('edit_others_car_offers')){$args['author']=get_current_user_id();}$query=new \WP_Query($args);$failed=(bool)$wpdb->last_error;
		echo '<div class="adc-table-scroll"><table class="widefat striped"><thead><tr>';foreach(array(self::t('العرض والسيارة','Offer and vehicle'),self::t('السعر بالريال','Price in SAR'),self::t('انتهاء العرض','Expiry'),self::t('النشر والظهور','Publication and visibility'),self::t('الإجراءات','Actions'))as$label){echo '<th scope="col">'.esc_html($label).'</th>';}echo '</tr></thead><tbody>';
		foreach($query->posts as$post){if(!current_user_can('edit_post',$post->ID)){continue;}$car=(int)get_post_meta($post->ID,'_offer_car_id',true);$visible=PublicOfferView::for_post($post->ID)!==null;
			echo '<tr><td><div class="adc-car-row">'.get_the_post_thumbnail($post->ID,array(90,65)).'<a href="'.esc_url(self::url($post->ID)).'">'.esc_html($post->post_title).'</a></div><small>'.esc_html($car&&current_user_can('read_post',$car)?get_the_title($car):self::t('لم تُحدد سيارة متاحة','No accessible vehicle selected')).'</small></td><td>'.esc_html(number_format_i18n((int)get_post_meta($post->ID,'_offer_new_price',true))).'</td><td>'.esc_html(get_post_meta($post->ID,'_offer_expires',true)?:self::t('دون تاريخ انتهاء','No expiry date')).'</td><td>'.esc_html($states[$post->post_status]??$post->post_status).'<br><small>'.esc_html($visible?self::t('ظاهر في الموقع','Visible on website'):self::t('غير ظاهر: راجع النشر والتوفر والسعر وتاريخ الانتهاء','Hidden: review publication, stock, price and expiry')).'</small></td><td>';
			if($post->post_status!=='trash'){echo '<a class="button" href="'.esc_url(self::url($post->ID)).'">'.esc_html(self::t('تعديل','Edit')).'</a> ';if($visible){echo '<a class="button" href="'.esc_url(get_permalink($post)).'">'.esc_html(self::t('عرض الموقع','View on site')).'</a> ';}}if(current_user_can('delete_post',$post->ID)){self::status_form($post->ID,$post->post_status==='trash'?'restore':'trash');}echo '</td></tr>';
		}if($failed||!$query->posts){echo '<tr><td colspan="5">'.esc_html($failed?self::t('تعذر تحميل العروض. أعد المحاولة.','Unable to load offers. Retry.'):self::t('لا توجد عروض مطابقة.','No matching offers.')).'</td></tr>';}echo '</tbody></table></div>';if($query->max_num_pages>1){echo '<nav class="adc-pagination">'.wp_kses_post(paginate_links(array('base'=>str_replace('99999999','%#%',add_query_arg('paged',99999999)),'format'=>'','current'=>$page,'total'=>$query->max_num_pages))).'</nav>';}
	}
	private static function field(string $name,string $label,string $value,string $type='text'):void {echo '<label class="adc-field">'.esc_html($label).'<input name="'.$name.'" type="'.$type.'" value="'.esc_attr($value).'"'.($type==='number'?' min="0" step="1"':($name==='title'?' required maxlength="200"':'')).'></label>';}
	private static function editor(int $id):void {
		$post=$id?get_post($id):null;if(($id&&(!$post||$post->post_type!=='car_offer'||!current_user_can('edit_post',$id)))||(!$id&&!current_user_can(get_post_type_object('car_offer')->cap->create_posts))){wp_die('Forbidden','',array('response'=>403));}
		echo '<p><a class="button" href="'.esc_url(self::url()).'">'.esc_html(self::t('العودة إلى العروض','Back to offers')).'</a></p>';if($post&&$post->post_status==='trash'){if(current_user_can('delete_post',$id)){self::status_form($id,'restore');}return;}
		echo '<form class="adc-publishing-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="adc_offer_save"><input type="hidden" name="post_id" value="'.$id.'"><input type="hidden" name="revision" value="'.esc_attr($id?Service::fingerprint($id):'').'">';wp_nonce_field('adc_offer_save');if(!$id){echo '<input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'">';}echo '<div class="adc-editor-grid"><main><section class="adc-panel"><h2>'.esc_html(self::t('بيانات العرض','Offer details')).'</h2>';self::field('title',self::t('اسم العرض','Offer title'),$post->post_title??'');
		$selected=(int)get_post_meta($id,'_offer_car_id',true);$cars=get_posts(array('post_type'=>'car','post_status'=>'publish','numberposts'=>-1,'orderby'=>'title','order'=>'ASC','suppress_filters'=>false));echo '<label class="adc-field">'.esc_html(self::t('السيارة المرتبطة','Linked vehicle')).'<select name="car_id"><option value="0">'.esc_html(self::t('اختر سيارة','Select a vehicle')).'</option>';$found=false;foreach($cars as$car){if(!current_user_can('read_post',$car->ID)){continue;}$found=$found||$selected===$car->ID;echo '<option value="'.$car->ID.'" '.selected($selected,$car->ID,false).'>'.esc_html($car->post_title).'</option>';}if($selected&&!$found){echo '<option selected value="'.$selected.'">'.esc_html((current_user_can('read_post',$selected)?get_the_title($selected):self::t('السيارة المرتبطة','Linked vehicle')).' — '.self::t('غير متوفرة للنشر حاليًا','Not currently available for publication')).'</option>';}echo '</select></label>';
		echo '<label class="adc-field">'.esc_html(self::t('ملخص العرض','Offer summary')).'<textarea name="summary" rows="3">'.esc_textarea($post->post_excerpt??'').'</textarea></label>';echo '<label class="adc-field">'.esc_html(self::t('وصف العرض وشروطه','Offer description and terms')).'<textarea name="description" rows="10">'.esc_textarea($post->post_content??'').'</textarea></label></section></main><aside><section class="adc-panel"><h2>'.esc_html(self::t('السعر والمدة','Price and duration')).'</h2><p>'.esc_html(self::t('اكتب الأسعار النهائية بالريال كما ستظهر للعميل، شاملة الضريبة والرسوم المطلوبة. لا تضاف ضريبة أخرى لهذه الحقول.','Enter final customer prices in whole SAR, including required VAT and fees. These fields do not add further VAT.')).'</p>';
		foreach(array('old_price'=>self::t('السعر السابق (اختياري)','Previous price (optional)'),'new_price'=>self::t('سعر العرض','Offer price'),'monthly_payment'=>self::t('القسط الشهري (اختياري)','Monthly payment (optional)'))as$key=>$label){self::field($key,$label,(string)(get_post_meta($id,'_offer_'.$key,true)?:0),'number');}self::field('expires',self::t('تاريخ الانتهاء (اختياري)','Expiry date (optional)'),(string)get_post_meta($id,'_offer_expires',true),'date');echo '</section><section class="adc-panel"><h2>'.esc_html(self::t('صورة العرض','Offer image')).'</h2><div data-media-field data-media-multiple="0"><h3>'.esc_html(self::t('اختيار صورة','Select image')).'</h3><input type="hidden" name="thumbnail_id" value="'.(int)get_post_thumbnail_id($id).'"><div class="adc-media-preview">'.(get_post_thumbnail_id($id)?'<figure data-image-id="'.(int)get_post_thumbnail_id($id).'">'.get_the_post_thumbnail($id,array(110,85)).'<button type="button" data-remove-image aria-label="'.esc_attr(self::t('إزالة الصورة','Remove image')).'">×</button></figure>':'').'</div><button type="button" class="button" data-select-images>'.esc_html(self::t('اختيار أو تغيير الصورة','Select or change image')).'</button></div><p>'.esc_html(self::t('عند غياب صورة العرض تستخدم صورة السيارة المرتبطة.','Without an offer image, the linked vehicle image is used.')).'</p></section><section class="adc-panel"><h2>'.esc_html(self::t('النشر','Publication')).'</h2><label class="adc-field">'.esc_html(self::t('حالة النشر','Publication status')).'<select name="status">';foreach(self::states()as$key=>$label){if(($key==='trash'||($key==='future'&&(!$post||$post->post_status!=='future')))||(!current_user_can('publish_car_offers')&&in_array($key,array('publish','private','future'),true))){continue;}echo '<option value="'.$key.'" '.selected($post->post_status??'draft',$key,false).'>'.esc_html($label).'</option>';}echo '</select></label><button class="button button-primary">'.esc_html(self::t('حفظ العرض','Save offer')).'</button></section></aside></div></form>';
	}
	private static function status_form(int $id,string $action):void {echo '<form class="adc-inline" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="adc_offer_status"><input type="hidden" name="post_id" value="'.$id.'"><input type="hidden" name="change" value="'.$action.'"><input type="hidden" name="revision" value="'.esc_attr(Service::fingerprint($id)).'">';wp_nonce_field('adc_offer_status');echo '<button type="submit" class="button">'.esc_html($action==='trash'?self::t('نقل للسلة','Move to trash'):self::t('استعادة كمسودة','Restore as draft')).'</button></form>';}
	private static function finish($result,string $url):void {if(is_wp_error($result)){set_transient('adc_offer_error_'.get_current_user_id(),$result->get_error_message(),120);}else{$url=add_query_arg('saved',1,$url);}wp_safe_redirect($url);exit;}
	public static function save():void {check_admin_referer('adc_offer_save');$input=wp_unslash($_POST);$result=empty($input['post_id'])&&(!is_string($input['request_key']??null)||!wp_is_uuid($input['request_key']))?new \WP_Error('adc_offer_invalid','Invalid offer request.'):Service::save($input);self::finish($result,is_wp_error($result)?(!empty($input['post_id'])?self::url(absint($input['post_id'])):add_query_arg('new',1,self::url())):self::url($result['id']));}
	public static function status():void {check_admin_referer('adc_offer_status');$result=Service::change_status(absint($_POST['post_id']??0),sanitize_key(wp_unslash($_POST['change']??'')),sanitize_text_field(wp_unslash($_POST['revision']??'')));self::finish($result,self::url());}
}
